#include <SPI.h>
#include <Adafruit_GFX.h>
#include <Adafruit_ST7789.h>

// IDEASSPARK ESP32 1.9" display pins
#define TFT_MOSI 23
#define TFT_SCLK 18
#define TFT_CS   15
#define TFT_DC    2
#define TFT_RST   4
#define TFT_BL   32

// Create the ST7789 display
Adafruit_ST7789 tft = Adafruit_ST7789(
  TFT_CS,
  TFT_DC,
  TFT_RST
);

void setup() {
  // Start serial communication
  Serial.begin(115200);
  delay(500);

  // Turn on the display backlight
  pinMode(TFT_BL, OUTPUT);
  digitalWrite(TFT_BL, HIGH);

  // Start SPI using the board's display pins
  SPI.begin(TFT_SCLK, -1, TFT_MOSI, TFT_CS);

  // Initialize the 1.9" 170x320 ST7789 display
  tft.init(170, 320, SPI_MODE3);

  // Landscape orientation
  tft.setRotation(1);

  // Clear the screen
  tft.fillScreen(ST77XX_BLACK);

  // Main message
  tft.setTextColor(ST77XX_YELLOW);
  tft.setTextSize(3);
  tft.setCursor(20, 35);
  tft.println("HELLO!");

  // Board name
  tft.setTextColor(ST77XX_WHITE);
  tft.setTextSize(2);
  tft.setCursor(20, 85);
  tft.println("IDEASSPARK");

  // Test message
  tft.setTextColor(ST77XX_CYAN);
  tft.setCursor(20, 120);
  tft.println("ESP32 TEST");

  // Serial confirmation
  Serial.println("DISPLAY TEST RUNNING");
}

void loop() {
  // Nothing needed for this test
}
